import { Mesh, MeshBasicNodeMaterial, PlaneGeometry, Quaternion } from 'three/webgpu';
import { texture, uv, vec2 } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const timelines = [];

  const imageUrl = config.assets?.imageUrl ?? '/prism-assets/chrome/ceramic-grain.map.png';
  const tex = ctx.textureLoader(imageUrl);

  const { sourceRect = [0, 0, 512, 320] } = config.atlasRegion ?? {};
  const [rx, ry, rw, rh] = sourceRect;

  const atlasWidth = tex.image?.width || 512;
  const atlasHeight = tex.image?.height || 320;

  const uvScale = vec2(rw / atlasWidth, rh / atlasHeight);
  const uvOffset = vec2(rx / atlasWidth, ry / atlasHeight);
  const mapNode = texture(tex, uv().mul(uvScale).add(uvOffset));

  const aspect = rw / rh;
  const geometry = new PlaneGeometry(aspect, 1);

  const material = new MeshBasicNodeMaterial({ transparent: false });
  material.mapNode = mapNode;

  const mesh = new Mesh(geometry, material);

  const pos = config.position ?? [3.2, -0.3, 0];
  const rot = config.rotation ?? [0, 0, 0];
  const scl = config.scale ?? [1, 1, 1];
  mesh.position.set(pos[0], pos[1], pos[2]);
  mesh.rotation.set(rot[0], rot[1], rot[2]);
  mesh.scale.set(scl[0], scl[1], scl[2]);

  const worldQ = new Quaternion();
  mesh.onBeforeRender = (renderer, scene, camera) => {
    if (mesh.parent && mesh.parent.type !== 'Scene') {
      mesh.parent.getWorldQuaternion(worldQ);
      worldQ.invert();
      worldQ.premultiply(camera.quaternion);
      mesh.quaternion.copy(worldQ);
    } else {
      mesh.quaternion.copy(camera.quaternion);
    }
  };

  for (const primitive of config.cinematicPrimitives ?? []) {
    if (ctx.primitives?.[primitive.name]) {
      ctx.primitives[primitive.name](mesh, primitive.params);
    }
  }

  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    timelines.forEach(tl => tl && tl.kill());
  };

  return mesh;
}
